fn dispatch_60416(payload: &[u8]) -> Option<usize> {
    let _ = payload;
    let m_0_8_u_0 = crate::engine::bits::extract_bits(payload, 0, 8, false, 0).map(|e| e.value);
    if m_0_8_u_0 == Some(16) { return Some(Idx::ISO_TRANSPORT_PROTOCOL_CONNECTION_MANAGEMENT_REQUEST_TO_SEND as usize); }
    if m_0_8_u_0 == Some(17) { return Some(Idx::ISO_TRANSPORT_PROTOCOL_CONNECTION_MANAGEMENT_CLEAR_TO_SEND as usize); }
    if m_0_8_u_0 == Some(19) { return Some(Idx::ISO_TRANSPORT_PROTOCOL_CONNECTION_MANAGEMENT_END_OF_MESSAGE as usize); }
    if m_0_8_u_0 == Some(32) { return Some(Idx::ISO_TRANSPORT_PROTOCOL_CONNECTION_MANAGEMENT_BROADCAST_ANNOUNCE as usize); }
    if m_0_8_u_0 == Some(255) { return Some(Idx::ISO_TRANSPORT_PROTOCOL_CONNECTION_MANAGEMENT_ABORT as usize); }
    None
}
